const validationErrors = [];
const chapterIsObject = $json.chapter !== null && typeof $json.chapter === 'object' && !Array.isArray($json.chapter);
const chapter = chapterIsObject ? $json.chapter : {};
if ($json.schema_version !== '1.0') validationErrors.push('Invalid schema_version: expected 1.0.');
if ($json.route !== 'chapter.persistence.created') validationErrors.push('Invalid route: expected chapter.persistence.created.');
if ($json.status !== 'ready') validationErrors.push('Invalid status: expected ready.');
if ($json.is_valid !== true) validationErrors.push('Input contract must be valid.');
if (!chapterIsObject) validationErrors.push('Invalid chapter: expected an object.');
for (const field of ['chapter_uuid','novel_uuid','workspace_uuid']) {
  if (typeof chapter[field] !== 'string' || !chapter[field].trim()) validationErrors.push(`chapter.${field} is required.`);
}
if (!Number.isInteger(chapter.chapter_number) || chapter.chapter_number < 1) validationErrors.push('chapter.chapter_number must be a positive integer.');
if (!Object.prototype.hasOwnProperty.call(chapter, 'chapter_title') || typeof chapter.chapter_title !== 'string') validationErrors.push('chapter.chapter_title must be a string; an empty string is allowed.');
return [{ json: { ...$json, is_valid: validationErrors.length === 0, validation_errors: validationErrors } }];

const chapter = $json.chapter && typeof $json.chapter === 'object' && !Array.isArray($json.chapter) ? $json.chapter : {};
return [{ json: {
  is_valid: $json.is_valid === true,
  validation_errors: $json.validation_errors ?? [],
  chapter_metadata: {
    chapter_uuid: chapter.chapter_uuid ?? '', novel_uuid: chapter.novel_uuid ?? '',
    workspace_uuid: chapter.workspace_uuid ?? '', chapter_number: chapter.chapter_number ?? 0,
    chapter_title: chapter.chapter_title ?? '',
  },
  source_content: typeof $json.chapter_content === 'string' ? $json.chapter_content : '',
} }];

return [{ json: { ...$json, canon_input: {
  canon_type: 'chapter',
  chapter_uuid: $json.chapter_metadata.chapter_uuid,
  novel_uuid: $json.chapter_metadata.novel_uuid,
  workspace_uuid: $json.chapter_metadata.workspace_uuid,
  chapter_number: $json.chapter_metadata.chapter_number,
  chapter_title: $json.chapter_metadata.chapter_title,
  source_content: $json.source_content,
} } }];

const input = $json.canon_input ?? {};
return [{ json: { ...$json, normalized_canon_input: {
  canon_type: 'chapter',
  chapter_uuid: typeof input.chapter_uuid === 'string' ? input.chapter_uuid.trim() : '',
  novel_uuid: typeof input.novel_uuid === 'string' ? input.novel_uuid.trim() : '',
  workspace_uuid: typeof input.workspace_uuid === 'string' ? input.workspace_uuid.trim() : '',
  chapter_number: input.chapter_number,
  chapter_title: typeof input.chapter_title === 'string' ? input.chapter_title.trim().replace(/\s+/gu, ' ') : '',
  source_content: typeof input.source_content === 'string' ? input.source_content.replace(/\r\n?/gu, '\n').trim() : '',
} } }];

function uuidHelper() {
  let timestamp = Date.now();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (token) => {
    const randomValue = (timestamp + Math.random() * 16) % 16 | 0;
    timestamp = Math.floor(timestamp / 16);
    return (token === 'x' ? randomValue : (randomValue & 0x3) | 0x8).toString(16);
  });
}
if ($json.is_valid !== true) return [{ json: { ...$json, canon_draft: null } }];
const input = $json.normalized_canon_input;
const timestamp = new Date().toISOString();
return [{ json: { ...$json, canon_draft: {
  canon_uuid: `CANON-${uuidHelper().replace(/-/g, '').slice(0, 8)}`,
  canon_type: input.canon_type, novel_uuid: input.novel_uuid, workspace_uuid: input.workspace_uuid,
  chapter_uuid: input.chapter_uuid, chapter_number: input.chapter_number, chapter_title: input.chapter_title,
  canon_version: '1.0', created_at: timestamp, updated_at: timestamp, created_by: 'Novel Studio WF-006',
} } }];

const validationErrors = [...($json.validation_errors ?? [])];
if ($json.is_valid === true) {
  const canon = $json.canon_draft ?? {};
  for (const field of ['canon_uuid','canon_type','novel_uuid','workspace_uuid','chapter_uuid','canon_version','created_at','updated_at','created_by']) {
    if (typeof canon[field] !== 'string' || !canon[field].trim()) validationErrors.push(`canon.${field} is required.`);
  }
  if (!Number.isInteger(canon.chapter_number) || canon.chapter_number < 1) validationErrors.push('canon.chapter_number must be a positive integer.');
  if (typeof canon.chapter_title !== 'string') validationErrors.push('canon.chapter_title must be a string.');
}
return [{ json: { ...$json, is_valid: validationErrors.length === 0, validation_errors: validationErrors } }];

const isValid = $json.is_valid === true;
return [{ json: {
  schema_version: '1.0', workflow_version: '2.0', route: 'canon.created', target: 'WF-007',
  status: isValid ? 'ready' : 'error', is_valid: isValid,
  validation_errors: $json.validation_errors ?? [], canon: isValid ? $json.canon_draft : null,
} }];
